<?php namespace App\Http\Controllers; use App\Http\Requests\StoreSaleRequest;use App\Models\Product;use App\Models\Sale;use App\Services\RecordSaleService;use Illuminate\Http\Request; class SaleController extends Controller { public function index(Request $r){$q=Sale::with('invoice');foreach(['customer_name','payment_status']as $f)if($r->$f)$q->where($f,'like',"%{$r->$f}%");if($r->from)$q->whereDate('sale_date','>=',$r->from);if($r->to)$q->whereDate('sale_date','<=',$r->to);return view('sales.index',['sales'=>$q->latest('sale_date')->paginate(15)]);}public function create(){return view('sales.form',['products'=>Product::where('status','active')->orderBy('name')->get()]);}public function store(StoreSaleRequest $r,RecordSaleService $s){$sale=$s->record($r->validated(),$r->user()->id);return redirect()->route('sales.show',$sale)->with('success','Sale recorded.');}public function show(Sale $sale){$sale->load('items.product','invoice');return view('sales.show',compact('sale'));} }